26:       noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true,
27:       systemPrompt: 'You are a helpful assistant.' });
28:     await resourceLoader.reload(); input.signal.throwIfAborted();
