30:       thinkingLevel: effort, tools: [], resourceLoader, settingsManager }, context);
31:     const cacheKey = `eval-${sha256(JSON.stringify([configured.provider, configured.modelId, effort, session.systemPrompt, context.contentHash]))}`;
32:     // Pi normally uses the unique session ID as its cache key. Keep independent audit IDs,
33:     // but route identical prefixes together. SSE prevents shared WebSocket conversation state.
34:     const stream = session.agent.streamFunction;
35:     session.agent.streamFunction = (model, history, options) => stream(model, history, { ...options, sessionId: cacheKey, transport: 'sse' });
