37:     let text: string | undefined, failure: string | undefined;
38:     const unsubscribe = session.subscribe(event => {
39:       if (event.type !== 'message_end' || event.message.role !== 'assistant') return;
40:       const message = event.message;
41:       for (const [key, value] of Object.entries(message.usage)) if (typeof value === 'number') usage[key] = (usage[key] ?? 0) + value;
42:       if (message.stopReason === 'error' || message.stopReason === 'aborted') failure = message.errorMessage || message.stopReason;
