47:     const timeout = setTimeout(() => { timedOut = true; abort(); }, EVAL_GENERATION_TIMEOUT_MS);
48:     input.signal.addEventListener('abort', abort, { once: true });
49:     try {
50:       input.signal.throwIfAborted();
51:       const supplementary = Object.keys(input.files).length ? `\n\n${JSON.stringify(input.files)}` : '';
52:       await session.prompt(input.prompt + supplementary);
53:       input.signal.throwIfAborted();
54:       if (timedOut) throw Error('Generation timed out.');
55:       if (failure) throw Error(`Eval agent failed: ${failure}`);
56:       if (text === undefined) throw Error('Eval agent returned no assistant response');
57:       // Malformed envelopes go through the existing bounded validation retry, with raw evidence retained.
58:       let output: unknown = text;
59:       try { output = JSON.parse(text); } catch { /* The workflow validator reports the envelope error. */ }
