367:     if (unknown) throw new ApplicationError('invalid-input', `Unknown input ${unknown}.`);
368:     const canvasSource = (name: string) => {
369:       const value = request.inputs[name];
370:       if ('agentContextId' in value) throw new ApplicationError('invalid-input', `Choose a canvas for ${name}.`);
371:       return { documentId: value.documentId, ...(value.viewId ? { viewId: value.viewId } : {}), checkpointId: value.checkpointId };
372:     };
373:     const keys = canvasInputs.map(input => JSON.stringify(canvasSource(input.name)));
374:     if (new Set(keys).size !== keys.length) throw new ApplicationError('invalid-input', 'Choose distinct canvases for each input.');
375:     if (request.workflow === 'alternatives') {
376:       for (const prompt of prompts) {
377:         const mentionsLayout = prompt.stages.alternative.includes('layout-template.json');
378:         if (!!layoutTemplate !== mentionsLayout) throw new ApplicationError('invalid-input', layoutTemplate
379:           ? 'Choose a template prompt that explicitly describes layout-template.json, or edit the prompt first.'
380:           : 'This prompt requires a layout template. Select one before starting.');
381:       }
382:     }
383:     const contexts: Record<string, EvalRunContext> = {};
384:     for (const input of contextInputs) {
385:       const value = request.inputs[input.name];
386:       if (!('agentContextId' in value)) throw new ApplicationError('invalid-input', `Choose an AgentContext for ${input.name}.`);
387:       const context = await this.contexts.read(value.agentContextId, false).catch(() => { throw new ApplicationError('invalid-input', 'That AgentContext is no longer available.'); });
388:       contexts[input.name] = { agentContextId: context.agentContextId, name: context.name, contentHash: context.contentHash };
389:     }
390:     const canvasSources = request.canvasSources ?? [];
391:     if (new Set(canvasSources.map(source => JSON.stringify(source))).size !== canvasSources.length)
392:       throw new ApplicationError('invalid-input', 'Choose distinct input canvases.');
393:     const canvasSetInputs = await Promise.all(canvasSources.map(async source => {
394:       const pinned = rerun?.canvasInputs?.find(copy => JSON.stringify(copy.source) === JSON.stringify(source));
395:       return pinned ? structuredClone(pinned) : (await this.comparisons.capture([source])).canvases[0];
396:     }));
397:     if (canvasSetInputs.some(copy => copy.view.generation && copy.view.generation.status !== 'finished'))
398:       throw new ApplicationError('invalid-input', 'Wait for input canvases to finish generating.');
399:     const previousIds = [...new Set(request.previous ?? [])];
400:     if (previousIds.length && request.workflow !== 'alternatives') throw new ApplicationError('invalid-input', 'Only Alternatives runs take earlier alternatives.');

401:     const previous = await Promise.all(previousIds.map(async id => {
402:       const pinned = rerun?.previous?.find(copy => copy.source.documentId === id);
403:       if (pinned) return structuredClone(pinned);
404:       const canvas = await this.canvases.read(id);
405:       if (!canvas) throw new ApplicationError('invalid-input', 'An earlier alternative is no longer available.');
406:       if (generatedWorkflow(canvas.generated) !== 'alternatives' || canvas.generated.agentContextId !== contexts.context?.agentContextId)
407:         throw new ApplicationError('invalid-input', 'Earlier alternatives must belong to the selected AgentContext and Alternatives workflow.');
408:       return (await this.comparisons.capture([{ documentId: id, checkpointId: canvas.history.headId }])).canvases[0];
409:     }));
410:     const captured = { projectId: (await this.projects.loadProject())?.id, canvases: await Promise.all(canvasInputs.map(async input => {
411:       const source = canvasSource(input.name);
412:       const pinned = Object.values(rerun?.inputs ?? {}).find(copy => JSON.stringify(copy.source) === JSON.stringify(source));
413:       return pinned ? structuredClone(pinned) : (await this.comparisons.capture([source])).canvases[0];
414:     })) };
415:     if (!captured.projectId) throw new ApplicationError('invalid-input', 'Open a project first.');
416:     const inputs = Object.fromEntries(canvasInputs.map(input => [input.name, captured.canvases.find(copy => JSON.stringify(copy.source) === JSON.stringify(canvasSource(input.name)))!]));
417:     if (Object.values(inputs).some(copy => copy.view.generation && copy.view.generation.status !== 'finished'))
418:       throw new ApplicationError('invalid-input', 'Wait for input canvases to finish generating.');
419:     // Outputs are owned by the chosen AgentContext; canvas-only workflows get a new context pinning their inputs.
420:     // Reruns stay under the original run's context.
421:     const owner = parent ? { agentContextId: parent.agentContextId, name: parent.contextName } : Object.values(contexts)[0];
422:     if (parent && contexts.context && contexts.context.agentContextId !== parent.agentContextId)
423:       throw new ApplicationError('invalid-input', 'A rerun must use the same AgentContext as its run.');
424:     const contextName = owner ? owner.name : `${workflow.label}: ${inputs[canvasInputs[0].name].view.name}`.slice(0, 120);
425:     const agentContextId = owner ? owner.agentContextId : (await this.contexts.create({ requestId: request.requestId, name: contextName,
426:       description: `${prompts.length} prompt${prompts.length === 1 ? '' : 's'} × ${request.passes} pass${request.passes === 1 ? '' : 'es'}`,
427:       context: JSON.stringify({ workflow: workflow.id, inputs: Object.fromEntries(Object.entries(inputs).map(([name, copy]) => [name, canvasContext(copy, false)])),
428:         prompts: prompts.map(({ name, version, stages }) => ({ name, version, stages })) }) })).agentContextId;
429:     if (request.workflow === 'few-shot-refinement') {
430:       if (prompts.length !== 1 || request.passes !== 3 || request.previous?.length) throw new ApplicationError('invalid-input', 'Few-shot refinement uses one prompt, three alternatives per round and three rounds.');
431:       if (!this.judgements || !this.layoutTemplates) throw new ApplicationError('invalid-input', 'Few-shot services are unavailable.');
432:       const target = firstTarget({ inputs });
433:       if (!layoutTemplate) layoutTemplate = await this.layoutTemplates.save({ requestId: request.requestId, name: `First diagram · ${inputs.target.view.name}`.slice(0, 120),
434:         capture: { source: inputs.target.source, geometry: { format: 'layout-template-v1', placement: { version: 2, gap: 3 }, slots: [{ id: 'slot-1',
435:           title: target.ascii!.split('\n').find(line => line.trim())!.trim().slice(0, 160), position: { column: 0, row: 0 },
436:           size: { columns: target.position.columns, rows: target.position.rows } }] } } });
437:       if (layoutTemplate.geometry.slots.length !== 1 || !layoutTemplate.geometry.slots[0].title) throw new ApplicationError('invalid-input', 'Select a single-diagram template with a title, or leave the template empty to capture the first target diagram.');
438:       // This experiment uses titles and dimensions only, even if an older template has descriptions.
439:       layoutTemplate.geometry.slots = layoutTemplate.geometry.slots.map(({ description: _, ...slot }) => slot);
440:     }
441:     const cells: EvalRunCell[] = request.workflow === 'few-shot-refinement' ? fewShotCells(prompts[0]) : prompts.flatMap(prompt => Array.from({ length: request.passes }, (_, i) => workflow.stages.map(stage => ({
442:       key: cellKey(prompt.promptId, i + 1, stage.id), promptId: prompt.promptId, promptVersion: prompt.version, promptName: prompt.name,
443:       pass: i + 1, stage: stage.id, status: 'queued' as const })))).flat();
444:     const run: EvalRun = { schemaVersion: 1, ...(reviewOnly ? {} : { number: this.nextNumber++ }), id: request.requestId, requestHash, request, references, projectId: captured.projectId, workflow: workflow.id,
445:       ...(layoutTemplate ? { layoutTemplate } : {}),
446:       ...(canvasSetInputs.length ? { canvasInputs: canvasSetInputs } : {}),
447:       agentContextId, contextName, prompts, inputs, ...(contextInputs.length ? { contexts } : {}), ...(previous.length ? { previous } : {}), status: 'queued', createdAt: new Date().toISOString(), cells,
448:       ...(parent ? { parentRunId: parent.id } : {}) };
449:     if (reviewOnly) return run;
450:     return this.launchPrepared(run);
451:   }
452:   /** Capture prompts and inputs without storing a runnable job or calling the model. */
453:   async prepareForReview(raw: unknown) {
454:     const request = evalRunRequestSchema.parse(raw);
455:     return this.prepare(request, sha256(JSON.stringify(request)), undefined, true);
456:   }
457:   async launchPrepared(prepared: EvalRun): Promise<EvalRun> {
458:     const active = this.preparedLaunches.get(prepared.id);
459:     if (active) return active;
460:     const pending = this.launchPreparedOnce(prepared);
461:     this.preparedLaunches.set(prepared.id, pending);
462:     try { return await pending; } finally { this.preparedLaunches.delete(prepared.id); }
463:   }
464:   private async launchPreparedOnce(prepared: EvalRun) {
465:     await this.ready;
466:     const existing = await this.store.read(prepared.id);
467:     if (existing) {
468:       if (existing.deletedAt) throw new ApplicationError('conflict', 'Planned run was deleted. Create a new experiment.');
469:       if (existing.requestHash !== prepared.requestHash) throw new ApplicationError('conflict', 'Run ID already used for another request.');
470:       return existing;
471:     }
472:     const run = structuredClone(prepared); run.number ??= this.nextNumber++; run.createdAt = new Date().toISOString();
473:     await this.store.save(run);
474:     const abort = new AbortController(); this.running.set(run.id, abort);
475:     const executing = structuredClone(run); this.live.set(run.id, executing);
476:     void this.execute(executing, abort.signal).finally(() => { this.running.delete(run.id); this.live.delete(run.id); }).catch(() => {});
477:     return run;
478:   }
479:   /** Saves are serialized so an older snapshot never replaces a newer one. */
480:   private persist(run: EvalRun) {
481:     if (this.deleted.has(run.id)) return Promise.resolve();
482:     const snapshot = structuredClone({ ...run, status: runStatus(run.cells) });
483:     const next = (this.saves.get(run.id) ?? Promise.resolve()).then(() => this.store.save(snapshot));
484:     this.saves.set(run.id, next.catch(() => {}));
485:     return next;
486:   }
487:   private async execute(run: EvalRun, signal: AbortSignal) {
488:     const project = await this.projects.loadProject();
489:     const catalog = await (this.projects.projectCatalogs.loadCurrentRepresentationCatalog?.(run.projectId, []) ?? this.projects.projectCatalogs.loadRepresentationCatalog(run.projectId));
490:     const anchor = run.inputs.parent ?? Object.values(run.inputs)[0];
491:     const repositoryId = (anchor && catalog.representations[anchor.source.documentId]?.repositoryId) ?? (project?.repositories?.length === 1 ? project.repositories[0].id : undefined);
492:     if (run.workflow === 'few-shot-refinement') {
493:       const context = run.contexts!.context;
494:       try {
495:         const saved = await this.contexts.read(context.agentContextId);
496:         if (saved.contentHash !== context.contentHash) throw Error('The AgentContext changed after the run started.');
497:         const contextFile = { name: saved.name, snapshot: saved.resolvedSnapshot ?? saved.snapshot };
498:         await executeFewShot({ run, runtime: this.runtime, judgements: this.judgements!, signal, context: contextFile, referenceLibrary: this.prompts.references, persist: () => this.persist(run),
499:           generate: async (cell, round, alternative, references) => {
500:             const prompt = run.prompts[0];
501:             await this.step(run, cell, signal, { workflow: run.workflow, stage: 'alternative', model: run.request.model, effort: run.request.effort,
502:               signal, body: prompt.stages.alternative, values: { context: saved.name, round: String(round), pass: '1', passes: '1', references: renderReferences(references.map(item => ({ name: item.title, ascii: item.ascii }))), previous: 'none' },
503:               schema: templateOutputSchema,
504:               files: { 'context.json': contextFile, 'layout-template.json': run.layoutTemplate!.geometry, 'few-shot.json': references.map(({ rationale: _, ...reference }) => reference) } },
505:               output => materializeTemplateAlternative(output, run.layoutTemplate!.geometry), `Round ${round} · alternative ${alternative}`, {
506:                 prompt: { id: prompt.promptId, version: prompt.version, name: prompt.name }, promptStages: { ...prompt.stages, references: JSON.stringify(references) }
507:               }, repositoryId);
508:           } });
509:       } catch (error) {
510:         run.error = error instanceof Error ? error.message : String(error);
511:         for (const cell of run.cells) if (cell.status === 'queued' || cell.status === 'generating') Object.assign(cell, { status: signal.aborted ? 'cancelled' : 'failed', error: run.error });
512:       }
513:       run.completedAt = new Date().toISOString(); await this.persist(run); return;
514:     }
515:     let preparedContext: AgentContextSnapshot | undefined;
516:     if (run.request.contextDelivery === 'session') {
517:       try {
518:         const context = run.contexts!.context;
519:         const saved = await this.contexts.read(context.agentContextId);
520:         if (saved.contentHash !== context.contentHash) throw Error('The AgentContext changed after the run started.');
521:         preparedContext = saved.resolvedSnapshot ?? saved.snapshot;
522:       } catch (error) {
523:         run.error = String(error);
524:         for (const cell of run.cells) Object.assign(cell, { status: signal.aborted ? 'cancelled' : 'failed', error: run.error });
525:         run.completedAt = new Date().toISOString(); await this.persist(run); return;
526:       }
527:     }
528:     const chains = run.prompts.flatMap(prompt => Array.from({ length: run.request.passes }, (_, i) => () => this.chain(run, prompt, i + 1, repositoryId, signal, preparedContext)));
529:     let next = 0;
530:     const worker = async () => { while (next < chains.length) await chains[next++]().catch(() => {}); };
531:     // Finish the first sample before sending the same prefix again. Different cases remain independent.
532:     await Promise.all(Array.from({ length: Math.min(preparedContext ? 1 : this.concurrency, chains.length) }, worker));
533:     run.completedAt = new Date().toISOString();
534:     if (signal.aborted) run.error = 'Run cancelled.';
535:     await this.persist(run);
536:   }
537:   private cell(run: EvalRun, prompt: EvalRunPrompt, pass: number, stage: string) {
538:     return run.cells.find(cell => cell.key === cellKey(prompt.promptId, pass, stage))!;
539:   }
540:   private async step<T extends { history: CanvasHistoryRecord; output: { explanation: string }; viewId?: string; layoutPlacements?: LayoutPlacement[] }>(run: EvalRun, cell: EvalRunCell, signal: AbortSignal,
541:     generation: Generation, validate: (output: unknown) => T, name: string, generated: Omit<GeneratedCanvas, 'key' | 'agentContextId' | 'contextName' | 'runId' | 'pass' | 'stage'>, repositoryId?: string) {
542:     Object.assign(cell, { status: 'generating', startedAt: new Date().toISOString() }); await this.persist(run);
543:     try {
544:       signal.throwIfAborted();
545:       const { result, usage, execution } = await this.generateValidated(generation, validate);
546:       signal.throwIfAborted();
547:       const document = documentFromHistory(result.history);
548:       const saved = await this.projects.projectCatalogs.saveMappingDiagram(run.projectId, { name: name.slice(0, 120), type: 'generated', history: result.history,
549:         scene: document.scene, edges: document.edges, repositoryId, generated: { ...generated, key: cell.key + ':' + run.id, agentContextId: run.agentContextId,
550:           contextName: run.contextName, runId: run.id, pass: cell.pass, stage: cell.stage as GeneratedCanvas['stage'], workflow: run.workflow,
551:           ...(run.layoutTemplate ? { layoutTemplate: run.layoutTemplate, layoutPlacements: result.layoutPlacements } : {}),
552:           ...(result.viewId ? { storageViewId: result.viewId } : {}) } });
553:       if (this.deleted.has(run.id)) { await this.projects.projectCatalogs.archiveRepresentation(run.projectId, saved.representation.id); signal.throwIfAborted(); }
554:       (run.outputSnapshots ??= {})[saved.representation.id] = { id: saved.representation.id, name, generated: saved.representation.generated!, history: copyCompareHistory(result.history, result.history.headId), placementSnapshot: placementSnapshot([{ id: saved.representation.id, scene: documentFromHistory(result.history).scene }]) };
555:       Object.assign(cell, { status: 'finished', canvasId: saved.representation.id, checkpointId: result.history.headId,
556:         ...(result.layoutPlacements ? { layoutPlacements: result.layoutPlacements } : {}),
557:         explanation: result.output.explanation, usage, execution, completedAt: new Date().toISOString() });
558:       await this.persist(run);
559:       return result;
560:     } catch (error) {
561:       Object.assign(cell, { status: signal.aborted ? 'cancelled' : 'failed', error: signal.aborted ? 'Cancelled.' : error instanceof Error ? error.message : String(error), completedAt: new Date().toISOString() });
562:       await this.persist(run);
563:       throw error;
564:     }
565:   }
566:   private async chain(run: EvalRun, prompt: EvalRunPrompt, pass: number, repositoryId: string | undefined, signal: AbortSignal, preparedContext?: AgentContextSnapshot) {
567:     const label = (copy: CompareCanvasCopy) => JSON.stringify(copy.view.name);
568:     const values = { ...Object.fromEntries(Object.entries(run.inputs).map(([name, copy]) => [name, label(copy)])),
569:       ...Object.fromEntries(Object.entries(run.contexts ?? {}).map(([name, context]) => [name, JSON.stringify(context.name)])),
570:       pass: '1', passes: '1', references: renderReferences(run.references ?? []),
571:       previous: run.previous?.length ? run.previous.map((copy, i) => `previous-${i + 1}.json (${JSON.stringify(copy.view.name)})`).join(', ') : 'none',
572:       ...Object.fromEntries(Object.entries(prompt.references ?? {}).map(([id, reference]) => [referenceKey(id), renderReference(reference.ascii, reference.comment)])) };
573:     const common = { workflow: run.workflow, model: run.request.model, effort: run.request.effort, signal, values, templateBase: prompt.templateBase };
574:     const provenance = { prompt: { id: prompt.promptId, version: prompt.version, name: prompt.name }, promptStages: structuredClone(prompt.stages) };
575:     const title = `${prompt.name} v${prompt.version} · sample ${pass}`;
576:     if (run.workflow === 'linked-canvases') {
577:       const cell = this.cell(run, prompt, pass, 'linked');
578:       Object.assign(cell, { status: 'generating', startedAt: new Date().toISOString() }); await this.persist(run);
579:       try {
580:         signal.throwIfAborted();
581:         const context = run.contexts!.context, saved = await this.contexts.read(context.agentContextId);
582:         if (saved.contentHash !== context.contentHash) throw Error('The AgentContext changed after the run started.');
583:         const canvasInputs = run.canvasInputs ?? [];
584:         const generated = await this.generateValidated({ ...common, stage: 'linked', body: prompt.stages.linked,
585:           schema: linkedCanvasesOutputSchema, files: {
586:             'context.json': { name: saved.name, description: saved.description, snapshot: saved.resolvedSnapshot ?? saved.snapshot },
587:             'canvases.json': canvasInputs.map((copy, i) => {
588:               const document = documentFromHistory(copy.history), context = canvasContext(copy, false);
589:               return { id: `c${i + 1}`, ...context, jumps: [
590:                 ...(document.jumps ?? []), ...context.diagrams.flatMap(d => {
591:                   const box = connectionBox(document.scene, d.id);
592:                   return box?.kind === 'diagram' ? (document.scene.contents[box.contentId].jumps ?? []).map(jump => ({ ...jump, sourceDisplayNodeId: d.id })) : [];
593:                 })
594:               ] };
595:             })
596:           } }, raw => materializeLinkedCanvases(raw, canvasInputs, `linked-${sha256(run.id + ':' + cell.key).slice(0, 16)}`));
597:         signal.throwIfAborted();
598:         (run.outputResults ??= {})[cell.key] = generated.result.result;
599:         Object.assign(cell, { output: summarizeEvalOutput(generated.result.result), status: 'finished',
600:           explanation: generated.result.output.explanation, usage: generated.usage, execution: generated.execution, completedAt: new Date().toISOString() });
601:         await this.persist(run);
602:       } catch (error) {
603:         Object.assign(cell, { status: signal.aborted ? 'cancelled' : 'failed', error: signal.aborted ? 'Cancelled.' : error instanceof Error ? error.message : String(error), completedAt: new Date().toISOString() });
604:         await this.persist(run); throw error;
605:       }

606:       return;
607:     }
608:     if (run.workflow === 'alternatives' || run.workflow === 'diagram-change-proposal') {
609:       const proposal = run.workflow === 'diagram-change-proposal';
610:       const stage = proposal ? 'proposal' : 'alternative';
611:       const context = run.contexts!.context, cell = this.cell(run, prompt, pass, stage);
612:       let saved;
613:       try {
614:         if (!preparedContext) {
615:           saved = await this.contexts.read(context.agentContextId);
616:           if (saved.contentHash !== context.contentHash) throw Error('The AgentContext changed after the run started.');
617:         }
618:       } catch (error) {
619:         Object.assign(cell, { status: 'failed', error: error instanceof Error ? error.message : String(error), completedAt: new Date().toISOString() });
620:         await this.persist(run); throw error;
621:       }
622:       await this.step(run, cell, signal,
623:         { ...common, stage, body: prompt.stages[stage],
624:           schema: proposal ? diagramChangeProposalSchema : run.layoutTemplate ? templateOutputSchema : alternativeOutputSchema,
625:           ...(preparedContext ? { agentContext: preparedContext } : {}),
626:           files: { ...(!preparedContext && saved ? { 'context.json': { name: saved.name, description: saved.description, snapshot: saved.resolvedSnapshot ?? saved.snapshot } } : {}),
627:             ...(run.layoutTemplate ? { 'layout-template.json': run.layoutTemplate.geometry } : {}),
628:             ...Object.fromEntries((run.previous ?? []).map((copy, i) => [`previous-${i + 1}.json`, canvasContext(copy, false)])) } },
629:         output => {
630:           if (proposal) {
631:             const { tree } = diagramChangeProposalSchema.parse(output);
632:             // Preserve syntax errors for the deterministic judge; never repair them during generation.
633:             cell.proposalTree = tree;
634:             return materializeAlternative({ explanation: 'Proposed diagram changes', diagrams: [{ id: 'proposal', ascii: tree, position: { column: 0, row: 0 } }], edges: [] });
635:           }
636:           return run.layoutTemplate ? materializeTemplateAlternative(output, run.layoutTemplate.geometry) : materializeAlternative(output);
637:         }, title, provenance, repositoryId);
638:       return;
639:     }
640:     const { child, parent } = run.inputs;
641:     const files = { 'child.json': canvasContext(child, false), 'parent-minimized.json': canvasContext(parent, true), 'parent-full.json': canvasContext(parent, false) };
642:     let r2;
643:     try {
644:       r2 = await this.step(run, this.cell(run, prompt, pass, 'r2'), signal, { ...common, stage: 'r2', body: prompt.stages.r2, schema: rollUpOutputSchema, files },
645:         materializeRollUp, `${title} · r2`, { ...provenance, source: child.source }, repositoryId);
646:     } catch (error) {
647:       Object.assign(this.cell(run, prompt, pass, 'g2'), { status: 'skipped', error: 'r2 did not finish.' }); await this.persist(run);
648:       throw error;
649:     }
650:     await this.step(run, this.cell(run, prompt, pass, 'g2'), signal,
651:       { ...common, stage: 'g2', body: prompt.stages.g2, schema: attachOutputSchema, files: { ...files, 'r2.json': r2.output } },
652:       output => materializeAttachment(parent.history, r2.output, output), `${title} · g2`, { ...provenance, source: parent.source }, repositoryId);
653:   }
654:   private async generateValidated<T>({ body, values, templateBase, ...input }: Generation, validate: (output: unknown) => T) {
655:     const workflow = evalWorkflows[input.workflow];
656:     const prompt = composePrompt(workflow, input.stage, body, values, templateBase);
657:     let files = input.files;
658:     const usage: Record<string, number> = {};
659:     for (let attempt = 0; ; attempt++) {
660:       input.signal.throwIfAborted();
661:       const response = await this.runtime.generate({ ...input, prompt, files }); input.signal.throwIfAborted();
662:       for (const [key, value] of Object.entries(response.usage ?? {})) usage[key] = (usage[key] ?? 0) + value;
663:       try { return { result: validate(response.output), usage, execution: response.execution }; }
664:       catch (error) {
665:         if (attempt >= 2) throw error;
666:         files = { ...input.files, 'previous-output.json': response.output, 'validation-error.json': { error: String(error) } };
667:       }
668:     }
669:   }
670:   /** Idempotent promotion of pre-Evals generated views. Original checkpoints remain available. */
671:   async migrate() {
672:     if (this.migration) return this.migration;
673:     this.migration = this.migrateLegacy();
674:     try { return await this.migration; } finally { this.migration = undefined; }
675:   }
676:   private async migrateLegacy() {
677:     const project = await this.projects.loadProject(); if (!project) return { migrated: 0 };
678:     const catalog = await (this.projects.projectCatalogs.loadCurrentRepresentationCatalog?.(project.id, []) ?? this.projects.projectCatalogs.loadRepresentationCatalog(project.id));
679:     // Archived keys also count: promotion must not resurrect a deleted output.
680:     const existing = new Set(Object.values(catalog.representations).map(c => c.generated?.key));
