94: export function runStatus(cells: EvalRunCell[]): EvalRunStatus {
95:   if (cells.some(cell => cell.status === 'generating')) return 'generating';
96:   if (cells.some(cell => cell.status === 'queued')) return cells.some(cell => cell.status !== 'queued') ? 'generating' : 'queued';
97:   if (cells.every(cell => cell.status === 'finished')) return 'finished';
98:   if (cells.some(cell => cell.status === 'finished')) return 'partial';
99:   return !cells.some(cell => cell.status === 'failed') && cells.some(cell => cell.status === 'cancelled') ? 'cancelled' : 'failed';
