102: export function legacyRollUpRun(run: RollUpRun): EvalRun {
103:   const passes = run.request.passes;
104:   const cells: EvalRunCell[] = [];
105:   for (let pass = 1; pass <= passes; pass++) for (const stage of ['r2', 'g2']) {
106:     const output = run.outputs.find(item => item.pass === pass && item.stage === stage);
107:     cells.push({ key: cellKey(undefined, pass, stage), pass, stage, canvasId: output?.canvasId, explanation: output?.explanation, usage: output?.usage,
108:       status: output ? 'finished' : run.status === 'failed' ? 'failed' : run.status === 'finished' ? 'skipped' : 'queued',
109:       ...(!output && run.status === 'failed' ? { error: run.error } : {}) });
110:   }
111:   return { schemaVersion: 1, id: run.id, requestHash: run.requestHash, projectId: run.projectId, workflow: 'roll-up', legacy: true,
112:     request: { requestId: run.id, workflow: 'roll-up', prompts: [], inputs: { child: run.request.child, parent: run.request.parent },
113:       passes, model: run.request.model, effort: run.request.effort as EvalRunRequest['effort'] },
114:     agentContextId: run.agentContextId, contextName: run.contextName, prompts: [], inputs: { child: run.child, parent: run.parent },
115:     status: run.status, createdAt: run.createdAt, completedAt: run.completedAt, error: run.error, cells };
116: }

