70: /** Polls quickly only while work is running. */
71: function usePolled<T>(load: () => Promise<T>, active: (value: T) => boolean, onError: (error: unknown) => void) {
72:   const [value, setValue] = useState<T>();
73:   const refresh = useRef<() => Promise<void>>(async () => {});
74:   const revision = useRef(0);
75:   useEffect(() => {
76:     let closed = false, timer: ReturnType<typeof setTimeout>;
77:     let inFlight: Promise<void> | undefined;
78:     const poll = (): Promise<void> => {
79:       if (inFlight) return inFlight;
80:       clearTimeout(timer);
81:       const at = revision.current;
82:       inFlight = (async () => {
83:         let next = 20000;
84:         try { const result = await load(); if (closed) return;
85:           if (at === revision.current) setValue(result);
86:           else next = 0;
87:           if (next && active(result)) next = 2500;
88:         } catch (error) { if (!closed) onError(error); }
89:         finally { inFlight = undefined; if (!closed) timer = setTimeout(() => void poll(), next); }
90:       })();
91:       return inFlight;
92:     };
93:     refresh.current = poll; void poll();
94:     return () => { closed = true; clearTimeout(timer); };
95:   }, []);
96:   const update = useCallback((change: (current: T | undefined) => T | undefined) => { revision.current++; setValue(change); }, []);
97:   return [value, useCallback(() => refresh.current(), []), update] as const;
98: }
