252:           && (!targets.runIds.length || !item.runIds.some(id => !targets.runIds.includes(id) && runs?.some(run => run.id === id)))) await deleteJudgement(item.id);
253:         const liveComparisons = await comparisonRuns();
254:         const comparisonIds = new Set([...targets.comparisonRunIds, ...liveComparisons.filter(item => targets.sessionIds.includes(item.sessionId ?? item.id)).map(item => item.id)]);
255:         for (const item of liveComparisons) if (comparisonIds.has(item.id)) await deleteComparisonRun(item.id);
256:         for (const item of await listCompareSessions()) if (targets.sessionIds.includes(item.id)) await deleteCompareSession(item.id);
257:         if (targets.runIds.length) await deleteRuns(targets.runIds);
258:         // Deleting runs already removes their output canvases.
259:         for (const item of await listGenerated()) if (targets.canvasIds.includes(item.id)) await deleteGenerated(item.id);
260:         setPicked(items => items.filter(item => !targets.canvasIds.includes(item.canvasId)));
261:       } catch (error) { await refreshAll(); throw error; }
262:     }, current => current.kind === 'run' ? targets.runIds.includes(current.id) || current.id === run?.id && !!shownCell?.canvasId && targets.canvasIds.includes(shownCell.canvasId)
263:       : current.kind === 'judgements' ? !!current.id && targets.runIds.includes(current.id)
264:       : current.kind === 'canvas' ? targets.canvasIds.includes(current.id)
265:       : current.kind === 'session' && (targets.sessionIds.includes(current.id) || targets.comparisonRunIds.includes(current.id))),
266:     open: target => target.kind === 'experiment' ? go(target) : target.kind === 'run' ? go({ kind: 'run', id: target.id, ...(target.output ? { output: target.output } : {}) })
267:       : target.kind === 'judgements' ? go({ kind: 'judgements', id: target.id, judgementId: target.judgementId })
268:       : target.kind === 'canvas' || target.kind === 'session' ? go({ kind: target.kind, id: target.id }) : undefined,
269:     deleteRun: item => {
270:       const family = [item, ...(runs ?? []).filter(other => other.parentRunId === item.id)];
271:       const outputs = family.reduce((sum, member) => sum + member.cells.filter(hasEvalOutput).length, 0);
272:       void remove(`Delete run #${numbers.get(item.id)}${family.length > 1 ? `, its ${family.length - 1} rerun${family.length > 2 ? 's' : ''}` : ''} and ${outputs} outputs?`,
273:         () => deleteRun(item.id), current => current.kind === 'run' && family.some(member => member.id === current.id));
274:     },
275:     deleteCanvas: (id, name) => void remove(`Delete output “${name}”?`, () => deleteGenerated(id),
276:       current => current.kind === 'canvas' && current.id === id || current.kind === 'run' && current.id === run?.id && shownCell?.canvasId === id,
277:       () => { updateGenerated(items => items?.filter(item => item.id !== id));
278:         updateRuns(items => items?.map(item => ({ ...item, cells: item.cells.map(cell => cell.canvasId === id ? { ...cell, deleted: true } : cell) })));
279:         setPicked(items => items.filter(item => item.canvasId !== id)); }),
280:     deleteContext: context => void remove(`Delete all ${context.outputs} outputs, runs and comparisons generated from “${context.name}” (${context.workflow === 'roll-up' ? 'roll-ups' : 'alternatives'})? The AgentContext itself is kept.`,
281:       () => deleteContextOutputs(context.id, context.workflow), current => current.kind === 'run' ? runs?.some(item => item.id === current.id && item.agentContextId === context.id && item.workflow === context.workflow) === true
282:         : current.kind === 'canvas' ? generated?.some(item => item.id === current.id && item.generated?.agentContextId === context.id && generatedWorkflow(item.generated) === context.workflow) === true
283:         : current.kind === 'session' && sessions?.some(item => item.id === current.id && !item.mixedOrigins && item.origins.length > 0 && item.origins.every(origin => origin.agentContextId === context.id && origin.workflow === context.workflow)) === true),
284:     runMenu: (item, at) => setMenu({ label: `Run #${numbers.get(item.id)}`, at, sections: [{ label: `Run #${numbers.get(item.id)} · ${item.contextName}`, items: [
285:       // Opens the exact version the run pinned; prompts deleted or unknown (legacy runs) are skipped.
286:       ...item.prompts.filter(pinned => prompts?.some(prompt => prompt.id === pinned.promptId)).map(pinned => ({
287:         label: item.prompts.length > 1 ? `Edit prompt “${pinned.name}”` : 'Edit prompt', detail: `v${pinned.version}`,
288:         onSelect: () => go({ kind: 'prompt', id: pinned.promptId, version: pinned.version }) })),
289:       ...(item.compatibility ? [{ label: 'Rerun with original chat settings', onSelect: () => void rerunChat(item.id, crypto.randomUUID()).then(started).catch(onError) }] : [{ label: 'Rerun…', onSelect: () => setLaunch({ workflow: item.workflow, rerun: item }) }]),
290:       ...(item.legacy ? [] : [{ label: 'Rename', onSelect: () => setRenaming(item.id) }]),
291:       ...(runActive(item) && !item.legacy ? [{ label: 'Cancel run', onSelect: () => void cancelRun(item.id).then(() => refreshRuns()).catch(onError) }] : []),
292:       { label: 'Delete run…', danger: true, onSelect: () => treeActions.deleteRun(item) }
293:     ] }] }),
294:     renameRun: (item, name) => void renameRun(item.id, name).then(() => refreshRuns()).catch(onError),
295:     contextMenu: (context, at) => setMenu({ label: context.name, at, sections: [{ label: context.name, items: [
296:       { label: 'New run from this context…', onSelect: () => {
297:         if (context.workflow !== 'roll-up') { setLaunch({ workflow: context.workflow, contextId: context.id }); return; }
298:         // Roll-ups reuse the latest run's child and parent canvases.
299:         const latest = context.runs[0];
300:         setLaunch({ workflow: 'roll-up', ...(latest ? { rerun: latest } : {}) });
301:       } },
302:       { label: 'Delete outputs…', danger: true, onSelect: () => treeActions.deleteContext({ id: context.id, name: context.name, workflow: context.workflow,
303:         outputs: context.outputs }) }
304:     ] }] }),
305:   };
306:   const openDiagram = (leaf: DiagramLeaf) => go({ kind: 'new-reference', target: { source: leaf.source, diagramId: leaf.diagram.diagramId } });
307:   const openReference = (id: string) => go({ kind: 'reference', id });
